begin;
do $$declare q record;pid uuid;data jsonb;rid uuid;code text;item uuid;denied boolean:=false;begin
select d.owner_id,d.monkey_id,(select id from auth.users where is_anonymous and id not in(select monkey_id from private.monkey_delegations) and id not in(select user_id from private.portal_accounts) limit 1) as player_user into q from private.monkey_delegations d where revoked_at is null and owner_id in(select user_id from private.portal_admins) limit 1;
assert q.player_user is not null;
perform set_config('request.jwt.claims',jsonb_build_object('sub',q.monkey_id,'role','authenticated')::text,true);
perform public.hud_player_registry(null,'__QA Workspace');
select (x->>'id')::uuid into pid from jsonb_array_elements(public.hud_player_registry())x where x->>'alias'='__QA Workspace';
perform public.hud_player_characters(pid,'save',null,'QA Traveller','A test character','');
data:=public.create_prepared_room(gen_random_uuid(),'__QA Workspace room','Owner','Day','Morning','mountain-path','','','An opening.','Explore',array[pid]);rid:=(data->>'id')::uuid;code:=data->'invitations'->0->>'code';
perform set_config('request.jwt.claims',jsonb_build_object('sub',q.player_user,'role','authenticated')::text,true);
perform public.portal_redeem(code,array['QA Traveller']);
data:=public.room_player_panel(rid,'QA Traveller');assert data->'scene'='null';assert data->'session'->>'starting_location'='Mountain Path';
perform public.change_character_inventory(rid,'QA Traveller','add',null,'Stone',3,'A smooth stone');data:=public.room_player_panel(rid,'QA Traveller');item:=(data->'inventory'->0->>'id')::uuid;
perform public.change_character_inventory(rid,'QA Traveller','remove',item,'',2,'');data:=public.room_player_panel(rid,'QA Traveller');assert (data->'inventory'->0->>'quantity')::int=1;assert jsonb_array_length(data->'changes')=2;
begin perform public.room_player_panel(rid,'Owner');exception when others then denied:=true;end;assert denied;denied:=false;
begin perform public.record_character_scene(rid,'QA Traveller','Secret palace','Invented');exception when others then denied:=true;end;assert denied;denied:=false;
begin perform public.change_character_inventory(rid,'QA Traveller','remove',item,'',2,'');exception when others then denied:=true;end;assert denied;
perform set_config('request.jwt.claims',jsonb_build_object('sub',q.monkey_id,'role','authenticated')::text,true);
perform public.record_character_scene(rid,'QA Traveller','Bathhouse','Steam curls above the water.');
perform public.record_character_scene(rid,'QA Traveller','Garden','A stone path borders the herb beds.');
assert jsonb_array_length(public.hud_location_ideas())>=2;
perform set_config('request.jwt.claims',jsonb_build_object('sub',q.player_user,'role','authenticated')::text,true);
data:=public.room_player_panel(rid,'QA Traveller');assert data->'scene'->>'location'='Garden';assert data->'session'->>'starting_location'='Mountain Path';
perform set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);denied:=false;
begin perform public.room_player_panel(rid,'QA Traveller');exception when others then denied:=true;end;assert denied;
assert not has_function_privilege('anon','public.room_player_panel(uuid,text)','execute');
end;$$;
select 'PASS: read-only session, no opening fallback, own inventory/audit, cross-character and non-member denial, owner-only scene history' as result;
rollback;
